import {initButtonEffects} from './button-effects.mjs?v=20261009-8';
import {createMusic} from './music.mjs?v=20261009-8';
import {bootProgress,finishBoot,failBoot} from './boot.mjs?v=20261009-8';
import {createStore} from './store.mjs?v=20261009-8';
import {createWheel,createEffects,SUCCESS_TIMING} from './motion.mjs?v=20261009-8';
import {createSound} from './sound.mjs?v=20261009-8';
import {initStarCursor} from './cursor.mjs?v=20261009-8';
import {resonanceSentences,meaningPreview} from './resonance.mjs?v=20261009-8';

const $=s=>document.querySelector(s),app=$('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let poems=[],byId,store,active,practice=null,view='home',detailId=null,listIds=[],listScroll=0,tab='all',query='',dynasty='',genre='',page=0,timer,noticeTimer,readReady=0,pointer=null,dirty=false;
let wheel=null,transitioning=false,flowToken=0,readyTimer,lastRouteKey=null;
const reduced=()=>systemMotion.matches;
const effects=createEffects(reduced);
const sound=createSound({enabled:()=>store?.state.soundEnabled??true,volume:()=>store?.state.soundVolume??.35});
const music=createMusic({enabled:()=>store?.state.musicEnabled??true,volume:()=>store?.state.musicVolume??.1});
function cancelFlow(){flowToken++;wheel?.destroy();wheel=null;effects.clear();sound.stop();clearTimeout(readyTimer);transitioning=false}
function updateSoundButton(){const b=$('#sound-toggle');if(b){b.textContent='音效';b.removeAttribute('aria-pressed');b.setAttribute('aria-label','音乐与音效设置')}const control=$('#sound-enabled');if(control){control.checked=store?.state.soundEnabled??true;const test=$('[data-action="sound-test"]');if(test)test.disabled=!control.checked}}
const systemMotion=matchMedia('(prefers-reduced-motion: reduce)');
function notice(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),3500)}
function saveError(){dirty=true;queueMicrotask(()=>notice('本次记录暂未保存，请在设置中重试或导出备份'))}
function count(){return Object.keys(store.state.completed).length}
function done(id){return !!store.state.completed[id]}
function fav(id){return !!store.state.favorites[id]?.on}
function current(){return practice||active}
function poem(){return byId.get(current().id)}
function fresh(id,mode='reading'){return {id,phase:mode==='review'?'read':'select',mode,candidate:-1,skipped:[],at:Date.now()}}
function saveSession(){if(!practice)store.session(active)}
function saveActive(){active.at=Date.now();saveSession()}
function motion(){document.body.classList.toggle('reduced',reduced());updateSoundButton()}
function navigate(v,id){clearTimeout(timer);location.hash=id?`${v}/${id}`:v;route()}
function route(e){if(!store)return;if(e?.type==='hashchange'&&location.hash===lastRouteKey)return;lastRouteKey=location.hash;cancelFlow();clearTimeout(timer);const parts=location.hash.slice(1).split('/');view=['home','library','detail','settings','audio'].includes(parts[0])?parts[0]:'home';if(view==='detail'){detailId=byId.has(parts[1])?parts[1]:poems[0].id}document.body.classList.toggle('panel',view!=='home');for(const b of document.querySelectorAll('nav button'))b.classList.toggle('active',(b.id==='sound-toggle'?'audio':b.dataset.action)===(view==='detail'?'library':view));render();window.scrollTo(0,view==='library'?listScroll:0)}
function render(){if(view==='home')renderHome();else if(view==='library')renderLibrary();else if(view==='detail')renderDetail();else if(view==='audio')renderAudio();else renderSettings()}
function progress(){const n=count();return `<aside class="progress-corner" aria-label="阅读进度"><div class="progress-label"><span>唐宋三百首 · 已点亮</span><span>${n} / 300</span></div><div class="track" role="progressbar" aria-label="全集完成进度" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="300"><span style="width:${n/3}%"></span></div></aside>`}
function resonance(p){return `<h3>此刻共鸣</h3><p class="resonance-tags">${p.tags.map(esc).join(' · ')}</p><div class="resonance-copy">${resonanceSentences(p).map(s=>`<p>${esc(s.text)}<span class="kaomoji">${esc(s.kaomoji)}</span></p>`).join('')}</div>`}
function meaningMarkup(p){const preview=meaningPreview(p.meaning),long=preview!==p.meaning;return `<div class="meaning-block"><h3>诗意今译${long?`<button data-action="meaning-toggle" class="meaning-toggle" aria-expanded="false" aria-controls="meaning-copy">展开</button>`:''}</h3><p id="meaning-copy" class="meaning-copy">${esc(preview)}</p></div>`}
function readingMarkup(p,success){return `<div class="quote-wrap"><div class="success-glow" aria-hidden="true"></div><h1 class="full-quote">${p.displayLines.map(line=>`<span class="quote-line">${Array.from(line).map(c=>success&&c===p.answer?`<mark>${esc(c)}</mark>`:esc(c)).join('')}</span>`).join('')}</h1>${success?Array.from({length:8},(_,i)=>`<i class="success-spark" aria-hidden="true" style="left:${34+(i*17)%34}%;top:${15+(i*23)%65}%" data-x="${Math.cos(i*.83)*55}" data-y="${Math.sin(i*.83)*35-16}"></i>`).join(''):''}</div><p class="byline">${esc(p.author)}《${esc(p.title)}》</p><div class="explanation reading-explanation">${meaningMarkup(p)}<div class="resonance-block">${resonance(p)}</div></div>`}
function renderHome({celebrate=false}={}){wheel?.destroy();wheel=null;effects.clear();clearTimeout(readyTimer);const s=current(),p=poem();if(s.phase==='end'){renderEnd();return}const read=s.phase==='read'||s.phase==='preview';app.innerHTML=`<section class="poetry-stage ${read?'reading':''} ${s.phase==='read'&&s.mode!=='review'?'success':''} ${celebrate?'celebrating':''}"><p class="chapter-note">${String(p.number).padStart(3,'0')} / 300${practice?' · 诗集练习':s.mode==='review'?' · 重读':''}</p>${read?readingMarkup(p,s.phase==='read'&&s.mode!=='review'):`<h1 class="sentence" aria-label="${esc(p.prompt.slice(0,p.blankIndex))}，缺一字，${esc(p.prompt.slice(p.blankIndex+1))}">${Array.from(p.prompt).map((c,i)=>i===p.blankIndex?`<span id="picker" class="picker" role="group" tabindex="0" aria-label="上下选择缺失的字">${['·',...p.options].map((letter,index)=>`<button class="picker-slot ${index===0?'blank-slot':''}" data-action="pick-index" data-index="${index-1}" tabindex="-1" aria-label="${index===0?'缺字空位':'选择 '+esc(letter)}">${esc(letter)}</button>`).join('')}</span>`:`<span>${esc(c)}</span>`).join('')}</h1><p class="instruction">上下滑动，寻一个恰好的字</p><div class="confirm-choice"><button id="confirm-choice" class="primary" data-action="confirm-choice" ${s.candidate<0?'hidden disabled':''}>确认</button></div><p id="feedback" class="feedback" role="status" aria-live="polite"></p><div class="utility"><button data-action="answer">看答案</button><button data-action="skip">稍后再读</button>${practice?'<button data-action="return-library">返回诗集</button>':''}</div>`}${read?`<div class="actions reading-actions"><button data-action="favorite" data-id="${p.id}" class="favorite ${fav(p.id)?'on':''}" aria-pressed="${fav(p.id)}">${fav(p.id)?'已收藏':'收藏此诗'}</button><button data-action="full" data-id="${p.id}">查看全文</button>${s.phase==='preview'?'<button data-action="retry" class="primary">再试一次</button>':practice?'<button data-action="return-library" class="primary">返回诗集</button>':`<button data-action="next" class="primary" ${celebrate?'disabled':''}>下一首</button>`}</div><p class="feedback">${s.phase==='preview'?'已查看答案，尚未点亮':s.mode==='review'?'重读不改变进度':''}</p>`:''}${progress()}</section>`;if(!read)bindPicker();else{readReady=Date.now()+(celebrate?(reduced()?180:SUCCESS_TIMING.ready-SUCCESS_TIMING.readDelay):0);if(celebrate){const root=$('.poetry-stage');effects.success(root);readyTimer=setTimeout(()=>{if(!root.isConnected)return;root.classList.remove('celebrating');root.querySelectorAll('[data-action="next"]').forEach(b=>b.disabled=false);transitioning=false},reduced()?180:SUCCESS_TIMING.ready-SUCCESS_TIMING.readDelay)}}}
function cancelJudge(){clearTimeout(timer)}
function select(index,judge=true){if(current().phase!=='select'||transitioning)return;wheel?.to(index,judge)}
async function checkAnswer(){const s=current();if(s.phase!=='select'||wheel?.dragging||transitioning||s.candidate<0)return;const p=poem();if(p.options[s.candidate]===p.answer){transitioning=true;const token=++flowToken;cancelJudge();s.phase='read';store.complete(p.id);saveSession();sound.success();const node=$(`#picker .picker-slot[data-index="${s.candidate}"]`);$('#picker')?.classList.add('confirming');await effects.glyph(node);if(token!==flowToken||view!=='home')return;renderHome({celebrate:true});notice('这一首，已点亮')}else{if($('#feedback'))$('#feedback').textContent='再斟酌一字';effects.wrong($('#picker'))}}
function bindPicker(){const el=$('#picker'),session=current();wheel=createWheel(el,{initial:session.candidate,reduced,onBegin:()=>{cancelJudge();const b=$('#confirm-choice');if(b)b.disabled=true},onGesture:()=>sound.unlock(),onTick:index=>sound.tick(index),onSettle:index=>{if(current()!==session||session.phase!=='select'||transitioning)return;session.candidate=index;saveSession();const f=$('#feedback');if(f)f.textContent='';el.setAttribute('aria-label',index<0?'上下选择缺失的字':`当前选字 ${poem().options[index]}，上下键切换`);const b=$('#confirm-choice');if(b){b.hidden=index<0;b.disabled=index<0;b.setAttribute('aria-label',index<0?'确认选字':`确认选字 ${poem().options[index]}`)}}})}
function continueReading(){practice=null;const p=poems.find(p=>!done(p.id))||poems[0];active=fresh(p.id);saveActive();navigate('home')}
async function next(skip=false){if(transitioning||(!skip&&current().phase==='read'&&Date.now()<readReady))return;transitioning=true;const token=++flowToken;cancelJudge();wheel?.destroy();wheel=null;await effects.exit($('.poetry-stage'));if(token!==flowToken)return;const s=current(),p=poem();if(practice){practice=null;navigate('library');transitioning=false;return}if(skip&&!s.skipped.includes(p.id))s.skipped.push(p.id);let nextP;if(s.mode==='reading'){const available=poems.filter(p=>!done(p.id)&&!s.skipped.includes(p.id)&&p.id!==s.id);nextP=available.find(x=>x.number>p.number)||available[0]}else nextP=poems.find(x=>x.number>p.number);if(nextP){const skipped=s.skipped;active=fresh(nextP.id,s.mode);active.skipped=skipped}else active.phase='end';saveActive();renderHome();transitioning=false;effects.enter($('.poetry-stage'));window.scrollTo(0,0)}
function renderEnd(){const all=count()===300;app.innerHTML=`<section class="poetry-stage"><div class="empty enter"><h1>${all?'三百首，皆已点亮':'这一程，暂且读到这里'}</h1><p>已点亮 ${count()} / 300 首${all?'':` · 还有 ${300-count()} 首待点亮`}</p><div class="actions">${all?'':'<button data-action="continue-reading" class="primary">继续待点亮作品</button>'}<button data-action="reread">从头重读</button><button data-action="library">打开诗集</button></div></div>${progress()}</section>`}

function normalized(s){return s.replace(/[\s，。！？；、·《》“”「」：,.!?;:'"\-]/g,'').toLowerCase()}
function filtered(){let list=poems.filter(p=>(tab==='all'||tab==='lit'&&done(p.id)||tab==='favorites'&&fav(p.id)||tab==='pending'&&!done(p.id))&&(!dynasty||p.dynasty===dynasty)&&(!genre||p.genre===genre)&&(!query||normalized(p.title+p.author+p.fullTextLines.join('')+p.quote).includes(normalized(query.trim()))));if(tab==='favorites')list.sort((a,b)=>store.state.favorites[b.id].at-store.state.favorites[a.id].at);return list}
function renderLibrary(){const list=filtered();listIds=list.map(x=>x.id);const pages=Math.max(1,Math.ceil(list.length/24));page=Math.max(0,Math.min(page,pages-1));app.innerHTML=`<section class="view enter"><div class="section-head"><h1>我的诗集</h1><button data-action="home">回到诗境</button></div><div class="tabs" role="tablist" aria-label="诗集状态">${[['all','全部',300],['lit','已点亮',count()],['favorites','已收藏',Object.values(store.state.favorites).filter(f=>f.on).length],['pending','待点亮',300-count()]].map(([key,label,n])=>`<button role="tab" aria-selected="${tab===key}" class="${tab===key?'selected':''}" data-action="tab" data-tab="${key}">${label} ${n}</button>`).join('')}</div><div class="filters"><input id="search" type="search" placeholder="寻一首诗、一位诗人、一句记忆" aria-label="搜索标题、作者或诗句" value="${esc(query)}"><select id="dynasty" aria-label="朝代"><option value="">所有朝代</option ${dynasty==='唐'?'selected':''}>唐</option><option ${dynasty==='宋'?'selected':''}>宋</option></select><select id="genre" aria-label="体裁"><option value="">所有体裁</option>${[...new Set(poems.map(p=>p.genre))].map(g=>`<option ${genre===g?'selected':''}>${esc(g)}</option>`).join('')}</select></div><p class="result-count">共 ${list.length} 首${query||dynasty||genre?' · <button data-action="clear-filters">清除筛选</button>':''}</p><div id="poem-results">${list.length?list.slice(page*24,(page+1)*24).map(p=>`<article class="poem-row"><span class="poem-number">${String(p.number).padStart(3,'0')}</span><button class="poem-link" data-action="detail" data-id="${p.id}"><strong>${esc(p.title)}</strong><small>${esc(p.author)} · ${p.era}</small><p>${esc(p.quote)}</p></button><span class="row-status">${done(p.id)?'已点亮':'待点亮'}</span><button data-action="favorite" data-id="${p.id}" class="favorite ${fav(p.id)?'on':''}" aria-pressed="${fav(p.id)}" aria-label="${fav(p.id)?'取消收藏':'收藏'}${esc(p.title)}">${fav(p.id)?'已收藏':'收藏'}</button></article>`).join(''):`<div class="empty"><p>${query||dynasty||genre?'没有找到相关诗词':tab==='favorites'?'还没有收藏，遇到喜欢的诗可以留下来':tab==='lit'?'还没有点亮的诗词，去读第一首':'三百首，皆已点亮'}</p><button data-action="${query||dynasty||genre?'clear-filters':'home'}" class="primary">${query||dynasty||genre?'清除筛选':'回到诗境'}</button></div>`}</div>${list.length>24?`<div class="pagination"><button data-action="prev-page" ${page===0?'disabled':''}>上一页</button><span>${page+1} / ${pages}</span><button data-action="next-page" ${page===pages-1?'disabled':''}>下一页</button></div>`:''}</section>`;const input=$('#search');let searchTimer;input.addEventListener('input',()=>{query=input.value;page=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=input.selectionStart;renderLibrary();$('#search').focus();if($('#search').type!=='search')$('#search').setSelectionRange(pos,pos)},200)});$('#dynasty').addEventListener('change',e=>{dynasty=e.target.value;page=0;renderLibrary()});$('#genre').addEventListener('change',e=>{genre=e.target.value;page=0;renderLibrary()})}
function renderDetail(){const p=byId.get(detailId),i=listIds.indexOf(p.id);app.innerHTML=`<section class="view detail enter"><div style="text-align:left"><button class="back" data-action="detail-back">返回${practice||detailFromHome?'诗境':'诗集'}</button></div><h1>${esc(p.title)}</h1><p class="byline">${esc(p.author)} · ${p.era} · ${esc(p.genre)}${done(p.id)?' · 已点亮':''}</p><div class="full-text">${p.fullTextLines.map(line=>line?`<p>${esc(line)}</p>`:'<div class="stanza"></div>').join('')}</div><blockquote>${esc(p.quote)}</blockquote><div class="explanation"><h3>诗眼 · ${esc(p.originalEye)}</h3>${p.originalEye!==p.answer?`<p style="font-size:14px;color:var(--muted)">本题选字：${esc(p.answer)}</p>`:''}<h3>诗意今译</h3><p class="long">${esc(p.meaning)}</p>${resonance(p)}</div><div class="actions"><button class="favorite ${fav(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-pressed="${fav(p.id)}">${fav(p.id)?'已收藏':'收藏此诗'}</button><button class="primary" data-action="practice" data-id="${p.id}">${done(p.id)?'再做选字':'选字点亮'}</button></div>${!detailFromHome?`<div class="pagination"><button data-action="detail-prev" ${i<=0?'disabled':''}>上一首</button><span>${Math.max(1,i+1)} / ${listIds.length||1}</span><button data-action="detail-next" ${i<0||i===listIds.length-1?'disabled':''}>下一首</button></div>`:''}</section>`}
let detailFromHome=false;
function renderSettings(){app.innerHTML=`<section class="view settings settings-hub enter"><div class="section-head"><h1>我的诗境</h1><button class="outlined" data-action="home">回到诗境 ↗</button></div><p class="intro">收藏走过的诗句，也留好一份备份。</p><div class="record-summary"><span class="summary-caption">唐宋三百首 · 本机进度</span><div class="record-numbers"><div><strong>${count()}</strong><span>首已点亮</span></div><div><strong>${Object.values(store.state.favorites).filter(f=>f.on).length}</strong><span>首已收藏</span></div></div><button class="outlined" data-action="library">打开我的诗集 <span aria-hidden="true">↗</span></button>${dirty?'<p>有记录尚未保存。</p><button class="primary" data-action="save-retry">重试保存</button>':''}</div><section class="backup-section"><h2>备份诗集</h2><p>换设备前，先把阅读与收藏记录带走。</p><div class="backup-actions"><button class="backup-action" data-action="export"><span class="action-symbol" aria-hidden="true">↓</span><span><strong>导出备份</strong><small>下载阅读与收藏记录</small></span><span class="action-arrow" aria-hidden="true">↗</span></button><button class="backup-action" data-action="import"><span class="action-symbol" aria-hidden="true">↑</span><span><strong>导入备份</strong><small>恢复记录，支持合并或替换</small></span><span class="action-arrow" aria-hidden="true">↗</span></button></div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="storage-note">记录保存在当前浏览器。清除浏览器数据前，请导出备份。</p></section><section class="reset-section"><div><h2>重新开始</h2><p>清除点亮、收藏与续读记录，诗词仍可阅读。</p></div><button class="danger-action" data-action="reset">清除个人记录</button></section></section>`;$('#import-file').addEventListener('change',importFile);}
function renderAudio(){app.innerHTML=`<section class="view settings enter"><div class="section-head"><h1>音乐与音效</h1><button data-action="home">回到诗境</button></div><p class="intro">留一点声音，伴你入境。</p><div class="setting-row"><h2>背景音乐</h2><label><input id="music-enabled" type="checkbox" ${store.state.musicEnabled?'checked':''}><span>伴着音乐读诗</span></label><label class="volume-control"><span>音量</span><input id="music-volume" type="range" min="0" max="1" step=".01" value="${store.state.musicVolume}" aria-label="背景音乐音量"><output id="music-output">${Math.round(store.state.musicVolume*100)}%</output></label><p id="music-status">${music.failed?'音乐暂未加载，可关闭后重新开启。':'默认 10% 轻声播放，可随心调节。'}</p></div><div class="setting-row"><h2>交互音效</h2><label><input id="sound-enabled" type="checkbox" ${(store.state.soundEnabled??true)?'checked':''}><span>滑动、点击与点亮铃音</span></label><label class="volume-control"><span>音量</span><input id="sound-volume" type="range" min="0" max="1" step=".01" value="${store.state.soundVolume??.35}" aria-label="音效音量"><output id="volume-output">${Math.round((store.state.soundVolume??.35)*100)}%</output></label><button data-action="sound-test" ${store.state.soundEnabled===false?'disabled':''}>试听确认音</button></div></section>`;$('#music-enabled').addEventListener('change',e=>{store.musicEnabled(e.target.checked);music.sync();if(e.target.checked)music.unlock()});$('#music-volume').addEventListener('input',e=>{store.musicVolume(Number(e.target.value));music.sync();$('#music-output').textContent=Math.round(Number(e.target.value)*100)+'%'});$('#sound-enabled').addEventListener('change',e=>{store.soundEnabled(e.target.checked);if(!e.target.checked)sound.stop();else sound.unlock();updateSoundButton()});$('#sound-volume').addEventListener('input',e=>{store.soundVolume(Number(e.target.value));$('#volume-output').textContent=Math.round(Number(e.target.value)*100)+'%'})}
async function ask(title,body){const d=$('#confirm');$('#confirm-title').textContent=title;$('#confirm-body').textContent=body;return new Promise(resolve=>{d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true});d.showModal()})}
async function importFile(e){const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('备份文件过大');const input=JSON.parse(await f.text()),data=store.validate(input);const n=Object.keys(data.completed).length,m=Object.values(data.favorites).filter(f=>f.on).length;const merge=await ask('合并备份',`备份包含 ${n} 首点亮记录、${m} 首收藏。合并会保留本机进度与当前会话。${data.unknown?'将忽略 '+data.unknown+' 条未知记录。':''}确认合并吗？`);if(merge){store.import(input);renderSettings();notice(dirty?'记录已合并，但部分尚未保存，请重试':'备份已合并');return}if(await ask('替换现有记录？',`替换后将变为 ${n} 首已点亮、${m} 首收藏。现有个人记录将被替换；取消则不导入。`)){store.import(input,true);active=validSession(store.state.session)||fresh(poems[0].id);practice=null;renderSettings();motion();notice('记录已替换')}}catch(err){notice(err.message||'备份无法读取，现有记录未改变')}finally{e.target.value=''}}
function validSession(s){if(!s||!byId.has(s.id)||!['reading','journey','review','practice'].includes(s.mode)||!['select','read','preview','end'].includes(s.phase))return null;if(s.mode==='practice')return null;return {...s,mode:s.mode==='journey'?'reading':s.mode,candidate:Number.isInteger(s.candidate)&&s.candidate>=-1&&s.candidate<5?s.candidate:-1,skipped:Array.isArray(s.skipped)?s.skipped.filter(id=>byId.has(id)):[]}}
async function action(e){const b=e.target.closest('[data-action]');if(!b||b.disabled||!store)return;const a=b.dataset.action,id=b.dataset.id;if(transitioning&&a==='confirm-choice')return;if(a!=='pick-index'&&a!=='sound-test')sound.click();if(a==='confirm-choice'){await checkAnswer();return}if(a==='meaning-toggle'){const expanded=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!expanded));b.textContent=expanded?'展开':'收起';$('#meaning-copy').textContent=expanded?meaningPreview(poem().meaning):poem().meaning;return}if(transitioning&&['confirm-choice','pick-index','answer','retry','skip','next','favorite','return-library'].includes(a))return;if(a==='pick-index'){const el=$('#picker');if(el?._suppressClickUntil>Date.now()||transitioning)return;const index=Number(b.dataset.index),nearest=Math.round(wheel?.position??-1);select(index===nearest?Math.min(poem().options.length-1,index+1):index);return}if(a==='sound-toggle'){navigate('audio');return}if(a==='sound-test'){await sound.unlock();sound.success();return}if(a==='home'){practice=null;detailFromHome=false;navigate('home')}else if(['library','settings','audio'].includes(a)){if(a==='library')listScroll=0;detailFromHome=false;navigate(a)}else if(a==='answer'){cancelJudge();current().phase='preview';saveSession();renderHome()}else if(a==='retry'){cancelJudge();transitioning=false;current().phase='select';current().candidate=-1;saveSession();renderHome()}else if(a==='skip')next(true);else if(a==='next')next();else if(a==='continue-reading')continueReading();else if(a==='reread'){practice=null;active=fresh(poems[0].id,'review');saveActive();navigate('home')}else if(a==='favorite'){store.favorite(id,!fav(id));notice(fav(id)?'已收藏':'已取消收藏');if(view==='home'){b.textContent=fav(id)?'已收藏':'收藏此诗';b.classList.toggle('on',fav(id));b.setAttribute('aria-pressed',fav(id))}else{const y=window.scrollY;render();window.scrollTo(0,y)}}else if(a==='detail'){listScroll=window.scrollY;detailFromHome=false;navigate('detail',id)}else if(a==='full'){detailFromHome=true;navigate('detail',id)}else if(a==='detail-back'){navigate(detailFromHome?'home':'library')}else if(a==='practice'){practice=fresh(id,'practice');navigate('home')}else if(a==='return-library'){practice=null;detailFromHome=false;navigate('library')}else if(a==='tab'){tab=b.dataset.tab;page=0;renderLibrary()}else if(a==='clear-filters'){query='';dynasty='';genre='';page=0;renderLibrary()}else if(a==='next-page'||a==='prev-page'){page+=a==='next-page'?1:-1;renderLibrary();window.scrollTo(0,0)}else if(a==='detail-next'||a==='detail-prev'){const i=listIds.indexOf(detailId),p=listIds[i+(a==='detail-next'?1:-1)];if(p)navigate('detail',p)}else if(a==='export'){const blob=new Blob([JSON.stringify(store.backup(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='tangsong-poetry-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('备份已导出')}else if(a==='import')$('#import-file').click();else if(a==='save-retry'){dirty=false;if(store.retry()){renderSettings();notice('记录已保存')}else dirty=true}else if(a==='reset'){if(await ask('清除个人记录？','已点亮、收藏与续读记录会被清除。建议先导出备份。')){if(!store.clear()){notice('记录未能清除，请重试');return}practice=null;active=fresh(poems[0].id);saveActive();motion();renderSettings();notice('个人记录已清除')}}}
document.addEventListener('click',action);
function unlockAudio(){sound.unlock();if(store)music.unlock()}
document.addEventListener('pointerdown',unlockAudio,{capture:true});
document.addEventListener('keydown',unlockAudio,{capture:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden){music.pause();cancelFlow();cancelJudge()}else{music.resume();if(store&&view==='home')renderHome()}});
app.addEventListener('click',e=>{if(view!=='home'||practice||current().phase!=='read'||Date.now()<readReady||e.target.closest('button,a,input,#picker,.explanation,.quote-wrap,.full-quote,.byline,.actions,aside')||getSelection()?.toString())return;if(e.target.classList.contains('poetry-stage'))next()});
window.addEventListener('hashchange',route);
window.addEventListener('storage',()=>{if(!store)return;cancelFlow();cancelJudge();store.reload();music.sync();render();motion()});
systemMotion.addEventListener('change',motion);
async function init(){try{bootProgress(15);const response=await fetch('poems.json?v=20261009-8');if(!response.ok)throw Error('无法加载诗词');poems=await response.json();if(poems.length!==300||new Set(poems.map(p=>p.id)).size!==300)throw Error('诗词数据不完整');bootProgress(55);byId=new Map(poems.map(p=>[p.id,p]));let storage;try{storage=localStorage}catch{storage={getItem(){throw Error()},setItem(){throw Error()},removeItem(){throw Error()},length:0};saveError()}store=createStore(storage,poems.map(p=>p.id),saveError);active=validSession(store.state.session)||fresh(poems[0].id);saveSession();motion();for(let i=0;i<22;i++){const star=document.createElement('i');star.className='star';star.style.cssText=`left:${(i*37.23)%100}%;top:${(i*13.71)%60}%;--duration:${4+i%5}s;--delay:-${i*.73}s`;$('#stars').append(star)}music.sync();bootProgress(75);route();registerTools();initButtonEffects();await finishBoot({music,sound})}catch(err){failBoot();app.innerHTML='<section class="empty"><h1>诗境暂未打开</h1><p>内容加载失败，已有个人记录不会被清除。</p><button class="primary" id="reload">重新打开</button></section>';$('#reload').onclick=()=>location.reload();console.error(err)}}
function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();const tool=(name,description,schema,execute,readOnly=false)=>{try{Promise.resolve(document.modelContext.registerTool({name,description,inputSchema:schema,execute,annotations:{readOnlyHint:readOnly,untrustedContentHint:false}},{signal:lifecycle.signal})).catch(()=>{})}catch{}};tool('read_poetry_progress','读取已点亮及收藏作品数量',{type:'object',properties:{},additionalProperties:false},()=>({completed:count(),total:300,favorites:Object.values(store.state.favorites).filter(f=>f.on).length}),true);tool('open_poem_detail','按作品ID打开诗词全文，不点亮作品',{type:'object',properties:{poemId:{type:'string'}},required:['poemId'],additionalProperties:false},input=>{if(!byId.has(input.poemId))throw Error('未知诗词ID');detailFromHome=false;navigate('detail',input.poemId);return {poemId:input.poemId,title:byId.get(input.poemId).title}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
initStarCursor();init();
